param([string]$BenchmarkRepo="D:\Dev\LotSizingDataModel.Benchmarks",[string]$ModelRepo="D:\Dev\LotSizingDataModel")
Set-StrictMode -Version Latest
$ErrorActionPreference="Stop"
function Ensure([string]$PathValue){if(-not(Test-Path -LiteralPath $PathValue -PathType Container)){New-Item -ItemType Directory -Path $PathValue -Force|Out-Null}}
$globalDir=Join-Path $BenchmarkRepo "catalog\global";$reportDir=Join-Path $BenchmarkRepo "reports\v0.21.0";$rawDir=Join-Path $BenchmarkRepo "benchmarks\EM1987\raw";$instanceDir=Join-Path $BenchmarkRepo "benchmarks\EM1987\instances";$metadataDir=Join-Path $BenchmarkRepo "benchmarks\EM1987\metadata";$docsDir=Join-Path $BenchmarkRepo "docs\benchmarks"
foreach($dir in @($reportDir,$rawDir,$instanceDir,$metadataDir,$docsDir)){Ensure $dir}
$rawFiles=@(Get-ChildItem -LiteralPath $rawDir -Filter "MARTIN*.dat" -File|Sort-Object Name);if($rawFiles.Count-ne17){throw "EM1987 raw file count must be 17."}
$importer=Join-Path $BenchmarkRepo "tools\EM1987Importer\EM1987Importer.csproj"
& dotnet run --project $importer -c Release -p:ModelRepo=$ModelRepo -- $rawDir $instanceDir $reportDir;if($LASTEXITCODE-ne0){throw "EM1987 conversion failed."}
$xml=@(Get-ChildItem -LiteralPath $instanceDir -Filter "*.xml" -File|Sort-Object Name);if($xml.Count-ne17){throw "EM1987 canonical count must be 17."}
$manifest=Join-Path $reportDir "EM1987-XML-MANIFEST.txt";[IO.File]::WriteAllLines($manifest,[string[]]$xml.FullName,(New-Object Text.UTF8Encoding($false)))
$fingerprints=Join-Path $metadataDir "EM1987-FINGERPRINTS-v0.21.0.csv";& dotnet run --project (Join-Path $BenchmarkRepo "tools\StadtlerBatchFingerprint\StadtlerBatchFingerprint.csproj") -c Release -p:ModelRepo=$ModelRepo -- EM1987 $manifest $fingerprints;if($LASTEXITCODE-ne0){throw "Fingerprinting failed."}
$fp=@(Import-Csv -LiteralPath $fingerprints);if($fp.Count-ne17){throw "EM1987 fingerprint count mismatch."}
$oldRegistry=@(Import-Csv -LiteralPath (Join-Path $globalDir "GLOBAL-BENCHMARK-REGISTRY-v0.16.4.csv"));if($oldRegistry.Count-ne7888){throw "Registry baseline mismatch."}
$oldTrust=@(Import-Csv -LiteralPath (Join-Path $globalDir "GLOBAL-NORMALIZED-TRUST-v0.20.0.csv"));if($oldTrust.Count-ne7888){throw "Trust baseline mismatch."}
$conversion=@(Import-Csv -LiteralPath (Join-Path $reportDir "EM1987-CONVERSION-MANIFEST.csv"));$conversionByXml=@{};foreach($c in $conversion){$conversionByXml[$c.xml_file]=$c}
$newRegistry=New-Object System.Collections.Generic.List[object];$newTrust=New-Object System.Collections.Generic.List[object]
foreach($f in $fp){$c=$conversionByXml[$f.filename];if($null-eq$c){throw "Missing conversion row for $($f.filename)"};$id=$c.instance_id;$sub=$c.subfamily;$gid="EM1987::$sub::$id";$sourcePath=Join-Path $rawDir ($id+".dat");$xmlPath=Join-Path $instanceDir $f.filename
  $newRegistry.Add([pscustomobject]@{global_instance_id=$gid;family="EM1987";subfamily=$sub;original_instance_id=$id;canonical_xml_path=$xmlPath;canonical_xml_sha256=(Get-FileHash -LiteralPath $xmlPath -Algorithm SHA256).Hash;source_role="CANONICAL_XML";source_sha256=(Get-FileHash -LiteralPath $sourcePath -Algorithm SHA256).Hash;planning_horizon=$c.periods;item_count=$c.items;work_center_count="1";lsdm_tags="Eppen-Martin|Eppen-Martin-1987|CLSP|single-level|capacitated|single-resource|$sub";lsdm_classification="CLSP; independent items; one capacitated work center; deterministic demand; setup cost/time, production cost/time, holding cost represented";fingerprint=$f.fingerprint;trust_status="NO_REFERENCE_KNOWN";objective_reference="";lower_bound="";complete_solution_available="False";checker_verified_solution="False";optimality_status="NOT_PROVEN";literature_source="Eppen and Martin (1987), DOI:10.1287/opre.35.6.832";duplicate_cluster_id="";genealogy_status="NO_EXACT_RELATION"})
  $newTrust.Add([pscustomobject]@{global_instance_id=$gid;family="EM1987";subfamily=$sub;original_instance_id=$id;canonical_xml_path=$xmlPath;fingerprint=$f.fingerprint;historical_trust_status="NO_REFERENCE_KNOWN";normalized_trust_status="NO_REFERENCE_KNOWN";normalization_basis="Source instance admitted; no objective value, complete solution, checker result, or optimality proof supplied";objective_reference="";lower_bound="";complete_solution_available="False";checker_verified_solution="False";optimality_status="NOT_PROVEN";literature_source="Eppen and Martin (1987), DOI:10.1287/opre.35.6.832"})
}
$registry=@($oldRegistry)+@($newRegistry.ToArray());$trust=@($oldTrust)+@($newTrust.ToArray());if($registry.Count-ne7905-or$trust.Count-ne7905){throw "Expanded cardinality mismatch."}
if(@($registry|Group-Object global_instance_id|Where-Object Count -gt 1).Count-ne0){throw "Global ID collision."};if(@($registry|Group-Object fingerprint|Where-Object Count -gt 1).Count-ne0){throw "Duplicate fingerprint detected; admission stopped."}
$registryCsv=Join-Path $globalDir "GLOBAL-BENCHMARK-REGISTRY-v0.21.0.csv";$registry|Export-Csv -LiteralPath $registryCsv -NoTypeInformation -Encoding UTF8;$registry|ConvertTo-Json -Depth 4|Set-Content -LiteralPath (Join-Path $globalDir "GLOBAL-BENCHMARK-REGISTRY-v0.21.0.json") -Encoding UTF8
$trust|Export-Csv -LiteralPath (Join-Path $globalDir "GLOBAL-NORMALIZED-TRUST-v0.21.0.csv") -NoTypeInformation -Encoding UTF8;$trust|ConvertTo-Json -Depth 4|Set-Content -LiteralPath (Join-Path $globalDir "GLOBAL-NORMALIZED-TRUST-v0.21.0.json") -Encoding UTF8
$family=@($registry|Group-Object family|Sort-Object Name|ForEach-Object{[pscustomobject]@{family=$_.Name;instances=$_.Count}});$family|Export-Csv -LiteralPath (Join-Path $globalDir "GLOBAL-FAMILY-SUMMARY-v0.21.0.csv") -NoTypeInformation -Encoding UTF8
$status=@($trust|Group-Object normalized_trust_status|Sort-Object Name|ForEach-Object{[pscustomobject]@{normalized_trust_status=$_.Name;instances=$_.Count;coverage_percent=[Math]::Round(100.0*$_.Count/$trust.Count,4)}});$status|Export-Csv -LiteralPath (Join-Path $globalDir "GLOBAL-TRUST-COVERAGE-v0.21.0.csv") -NoTypeInformation -Encoding UTF8
$missing=@(
 [pscustomobject]@{family="TTM1989";roadmap_role="confirmed mirror";canonical_instances=0;missing="public/original raw instance files and verifiable source lineage";known_reference="Trigeiro, Thomas and McClain (1989)";acquisition_status="NOT_ACQUIRED"},
 [pscustomobject]@{family="DIABY1992";roadmap_role="acquisition target";canonical_instances=0;missing="benchmark instance files, solutions and provenance";known_reference="DOI:10.1016/0377-2217(92)90201-J";acquisition_status="NOT_ACQUIRED"},
 [pscustomobject]@{family="DS1981";roadmap_role="bibliographic";canonical_instances=0;missing="benchmark instance files and machine-readable definitions";known_reference="DOI:10.1016/0272-6963(81)90033-4";acquisition_status="NOT_ACQUIRED"},
 [pscustomobject]@{family="MAESVW";roadmap_role="generator target";canonical_instances=0;missing="generator specification, parameters, seeds and reference implementation";known_reference="roadmap entry";acquisition_status="SPECIFICATION_REQUIRED"},
 [pscustomobject]@{family="HAASE1996";roadmap_role="generator target";canonical_instances=0;missing="generator specification, parameters, seeds and reference implementation";known_reference="roadmap entry";acquisition_status="SPECIFICATION_REQUIRED"})
$missing|Export-Csv -LiteralPath (Join-Path $globalDir "MISSING-FAMILY-ACQUISITION-v0.21.0.csv") -NoTypeInformation -Encoding UTF8
$quality=@([pscustomobject]@{check="registry_rows";expected="7905";observed=$registry.Count;status="PASS"},[pscustomobject]@{check="EM1987_rows";expected="17";observed=$newRegistry.Count;status="PASS"},[pscustomobject]@{check="global_id_duplicates";expected="0";observed="0";status="PASS"},[pscustomobject]@{check="fingerprint_duplicate_clusters";expected="0";observed="0";status="PASS"},[pscustomobject]@{check="canonical_XML_rewritten";expected="0 existing";observed="0 existing; 17 added";status="PASS"});$quality|Export-Csv -LiteralPath (Join-Path $reportDir "DATA-QUALITY-v0.21.0.csv") -NoTypeInformation -Encoding UTF8
$md="# v0.21.0 - Eppen-Martin admission and acquisition closure`r`n`r`nThis roadmap-aligned pack admits the complete 17-file EM1987 source archive without fabricating reference objectives or proofs. The global registry grows from 7,888 to 7,905 canonical instances. Five other roadmap families remain explicit acquisition targets in ``MISSING-FAMILY-ACQUISITION-v0.21.0.csv``. Existing canonical XML is not rewritten.`r`n";[IO.File]::WriteAllText((Join-Path $docsDir "EM1987-ADMISSION-v0.21.0.md"),$md,(New-Object Text.UTF8Encoding($false)))
Write-Host "EM1987_ADMISSION_V0.21.0";Write-Host("ROWS|"+$registry.Count);Write-Host("EM1987|"+$newRegistry.Count);Write-Host "DUPLICATE_CLUSTERS|0";Write-Host("MISSING_FAMILIES|"+$missing.Count)
